	private GenericPlanNode explain(String query) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return connection.prepareTupleQuery(query)
					.explain(Explanation.Level.Telemetry)
					.toGenericPlanNode();
		}
	}

	private List<BindingSet> evaluate(String query, boolean nativeEngine) {
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEngine));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
		} finally {
			System.setProperty(NATIVE_FLAG, "true");
		}
	}

	private static Set<String> executionPaths(GenericPlanNode root) {
		Set<String> paths = new LinkedHashSet<>();
		collectExecutionPaths(root, paths);
		return paths;
	}

	private static void collectExecutionPaths(GenericPlanNode node, Set<String> paths) {
		if (node == null) {
			return;
		}
		String path = node.getStringMetricActual(EXECUTION_PATH_METRIC);
		if (path != null) {
			for (String tag : path.split("\\|")) {
				paths.add(tag.trim());
			}
		}
		if (node.getPlans() != null) {
			node.getPlans().forEach(child -> collectExecutionPaths(child, paths));
		}
	}

